const shiftQuantitySales = `-- name: ShiftQuantitySales :many
select l.variant_id, v.alcocode, sum(l.qty)::integer as qty
from pos_receipt_lines l
join pos_receipts r on r.id = l.receipt_id
join variants v on v.id = l.variant_id
join products p on p.id = v.product_id
join product_kinds k on k.code = p.kind_code
where r.shift_id = $1 and k.egais_accounting = 'quantity'
group by l.variant_id, v.alcocode
having sum(l.qty) > 0
`

type ShiftQuantitySalesRow struct {
	VariantID uuid.UUID
	Alcocode  *string
	Qty       int32
}

// Проданное за смену пиво и другая продукция без марок: акт списания из зала «Реализация».
func (q *Queries) ShiftQuantitySales(ctx context.Context, shiftID uuid.UUID) ([]ShiftQuantitySalesRow, error) {
	rows, err := q.db.Query(ctx, shiftQuantitySales, shiftID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ShiftQuantitySalesRow
	for rows.Next() {
		var i ShiftQuantitySalesRow
		if err := rows.Scan(&i.VariantID, &i.Alcocode, &i.Qty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const shiftTotals = `-- name: ShiftTotals :one
select count(*) filter (where kind = 'sale')::integer as receipts,
       count(*) filter (where kind = 'return')::integer as returns,
       coalesce((sum(case when kind = 'sale' then total else -total end) filter (where payment = 'cash')) * 100, 0)::bigint as cash_kopecks,
       coalesce((sum(case when kind = 'sale' then total else -total end) filter (where payment = 'card')) * 100, 0)::bigint as card_kopecks
from pos_receipts
where shift_id = $1
`

type ShiftTotalsRow struct {
	Receipts    int32
	Returns     int32
	CashKopecks int64
	CardKopecks int64
}

func (q *Queries) ShiftTotals(ctx context.Context, shiftID uuid.UUID) (ShiftTotalsRow, error) {
	row := q.db.QueryRow(ctx, shiftTotals, shiftID)
	var i ShiftTotalsRow
	err := row.Scan(
		&i.Receipts,
		&i.Returns,
		&i.CashKopecks,
		&i.CardKopecks,
	)
	return i, err
}

const tobaccoMinPrice = `-- name: TobaccoMinPrice :one
select (price * 100)::bigint as kopecks
from tobacco_min_prices
where valid_from <= ($1::timestamptz at time zone 'Europe/Moscow')::date
order by valid_from desc
limit 1
`

// ЕМЦ табачной продукции на дату по Москве: федеральная величина действует с начала суток по Москве.
func (q *Queries) TobaccoMinPrice(ctx context.Context, at time.Time) (int64, error) {
	row := q.db.QueryRow(ctx, tobaccoMinPrice, at)
	var kopecks int64
	err := row.Scan(&kopecks)
	return kopecks, err
}

const touchDevice = `-- name: TouchDevice :exec
update pos_devices set last_seen_at = now() where id = $1
`

func (q *Queries) TouchDevice(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, touchDevice, id)
	return err
}
